class LmdbLegacyV4EarlyFenceTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:v4-early-fence:p");

	@Test
	void registeredAlternateSnapshotIsFencedBeforeDeferredConfiguration(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbLegacyV4TestFixture.install(directory);
		Path legacy = directory.resolve("join-estimator.rjes");
		CopyOnWriteArrayList<Statement> rows = new CopyOnWriteArrayList<>();
		AtomicInteger scans = new AtomicInteger();
		rows.add(row(1));
		SketchStatementSource source = (s, p, o, c) -> {
			scans.incrementAndGet();
			return new CloseableIteratorIteration<>(rows.iterator());
		};
		try (AutoCloseable preserve = () -> LmdbLegacyV4TestFixture.assertUnchanged(directory)) {
			try (SketchBasedJoinEstimator seed = estimator(source)) {
				seed.configurePersistence(legacy, false);
				seed.synopsisService().requestRebuild();
				assertTrue(seed.forceFlush());
				assertEquals(1.0d, rows(seed).rows().estimate(), 0.0d);
				seed.persistIfDirty();
			}
			int previousScans = scans.get();
			try (SketchBasedJoinEstimator early = estimator(source)) {
				early.registerPersistencePath(legacy);
				assertEquals(previousScans, scans.get(), "registration does not scan or load the saved synopsis");
				assertFalse(early.isReadyNonBlocking());
				early.setRebuildAllowedSupplier(() -> false);
				try (var fence = early.beginStoreCommit()) {
					rows.add(row(2));
					early.addStatement(row(2));
					fence.reconciled();
				}
			}
			try (SketchBasedJoinEstimator reopened = estimator(source)) {
				reopened.setRebuildAllowedSupplier(() -> false);
				reopened.configurePersistence(legacy, true);
				assertFalse(reopened.isReadyNonBlocking(), "the earlier snapshot was fenced before source mutation");
				assertFalse(rows(reopened).usable(), "stale rows are unavailable before a rebuild");
				reopened.setRebuildAllowedSupplier(() -> true);
				assertTrue(reopened.forceFlush());
				assertTrue(rows(reopened).usable());
				assertEquals(2.0d, rows(reopened).rows().estimate(), 0.0d);
			}
		}
		LmdbLegacyV4TestFixture.assertUnchanged(directory);
	}

	private static SketchBasedJoinEstimator estimator(SketchStatementSource source) {
		return new SketchBasedJoinEstimator(source,
				SketchBasedJoinEstimator.Config.defaults().withMemoryBudgetBytes(4L * 1024L * 1024L));
	}

	private static Statement row(int number) {
		return VF.createStatement(VF.createIRI("urn:v4-early-fence:s" + number), P, VF.createLiteral(number));
	}

	private static QuadEvidence rows(SketchBasedJoinEstimator estimator) {
		return estimator.synopsisService()
				.probe(new QuadProbe(QuadProbe.PREDICATE, QuadProbe.SUBJECT, 0L,
						QuadValueHash.hash(P), 0L, 0L, estimator.quadSnapshotIdentity()));
	}
}
